import{_ as e,o as i,c as o,ag as t}from"./chunks/framework.KxDd3USm.js";const s=JSON.parse('{"title":"02.9 精华题与补充题","description":"","frontmatter":{},"headers":[],"relativePath":"02-数据库系统/91-精华题与补充题.md","filePath":"02-数据库系统/91-精华题与补充题.md"}'),a={name:"02-数据库系统/91-精华题与补充题.md"};function p(r,l,A,_,C,n){return i(),o("div",null,[...l[0]||(l[0]=[t('<h1 id="_02-9-精华题与补充题" tabindex="-1">02.9 精华题与补充题 <a class="header-anchor" href="#_02-9-精华题与补充题" aria-label="Permalink to &quot;02.9 精华题与补充题&quot;">​</a></h1><ol><li><p>【三级模式】视图属于三级模式结构中的（ ）；在数据库中存储索引的组织方式属于（ ）。</p></li><li><p>【自然连接】设 R(A,B,C) 有 2 行，S(B,D) 有 3 行，公共属性 B。R 与 S 自然连接结果的列数为（ ）？行数最多可能是多少？</p></li><li><p>【范式判定】有关系模式 R(仓库号, 仓库面积, 城市, 地区编号)，函数依赖：仓库号→城市，仓库号→仓库面积，城市→地区编号。判断 R 最高属于第几范式，并分解到该范式。</p></li><li><p>【候选键】关系模式 R(A,B,C,D,E)，F = {A→B, C→D, E→A, B→C}。求 R 的候选键。</p></li><li><p>【并发控制】设 A 初值为 50。T1：读 A，A←A+20，写回；T2：读 A，A←A×2，写回。若两事务并发执行且发生&quot;丢失修改&quot;，最终 A 的值可能错误地变成多少？正确值应为多少？</p></li><li><p>【SQL 综合】针对学生表 Student(Sno, Sname, Dept)、课程表 Course(Cno, Cname)、选课表 SC(Sno, Cno, Grade)： (1) 查询选修了&quot;C02&quot;课程的学生姓名（用嵌套查询）； (2) 查询选修课程门数超过 3 门的学生学号； (3) 把查询 SC 表的权限授予用户 U1，并允许其转授。</p></li><li><p>【概念辨析】&quot;某个事务对同一数据的两次读取结果不同&quot;与&quot;读到未提交的数据&quot;分别对应哪类并发错误？</p></li></ol><hr><h2 id="补充题-扩充考点专项-不破坏原题编号" tabindex="-1">补充题（扩充考点专项，不破坏原题编号） <a class="header-anchor" href="#补充题-扩充考点专项-不破坏原题编号" aria-label="Permalink to &quot;补充题（扩充考点专项，不破坏原题编号）&quot;">​</a></h2><ol><li><p>【属性闭包】关系模式 R(A,B,C,D,E)，F={A→BC，B→D，CD→E，E→A}。分别求 A⁺ 与 C⁺，并判断 A、C 是否为候选键。</p></li><li><p>【多个候选键与范式】关系模式 R(A,B,C)，F={AB→C，C→B}。求全部候选键、主属性，并判断最高范式。</p></li><li><p>【无损连接】R(A,B,C)，F={A→B}。下列哪个二元分解可用“公共属性决定其中一表”直接判为无损？ A. R1(A,B)、R2(A,C) B. R1(A,B)、R2(B,C) C. 两者都可以 D. 两者都不可以</p></li><li><p>【自然连接行数】R(A,B) 的三行是 <code>(r1,x)、(r2,x)、(r3,y)</code>；S(B,C) 的三行是 <code>(x,s1)、(x,s2)、(z,s3)</code>。R⋈S 有多少行、多少列？</p></li><li><p>【EXISTS】把“查询选修 C02 的学生姓名”写成相关 <code>EXISTS</code> 子查询，并说明关联条件为何不能省略。</p></li><li><p>【锁相容】事务 T1 已对数据 A 加 S 锁。此时 T2 对 A 的哪种申请可以立即获准？ A. 只可申请 S 锁 B. 只可申请 X 锁 C. S、X 都可 D. S、X 都不可</p></li><li><p>【幻读】T1 两次执行相同的范围查询，期间 T2 插入一条满足条件的记录并提交，导致第二次多出一行。这属于（ ）。 A. 丢失修改 B. 读脏数据 C. 不可重复读 D. 幻读</p></li><li><p>【故障恢复】系统日志中 T1 已出现 COMMIT，T2 只有 BEGIN 和更新记录；随后主机断电，但磁盘未损坏。故障类型及恢复动作是什么？</p></li><li><p>【分布式数据库】“用户不必知道一张全局关系被水平切成哪些片段”属于哪种透明性？“某站点故障后仍可从其他副本提供服务”体现哪种特性？</p></li></ol><hr>',6)])])}const B=e(a,[["render",p]]);export{s as __pageData,B as default};
